var i=`0276-potica`;var t=`world-0276`;var o=`SI`;var a=`southern-europe`;var l=8;var r=138;var s={en:`Potica`,ua:`Потіца`};var u={en:`A traditional Slovenia dish made with all-purpose flour, whole cow milk, instant yeast, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Словенія. Основні інгредієнти: пшеничне борошно універсальне, цільне коров'яче молоко, інстантні дріжджі, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,550,`g`],[`whole-cow-milk`,240,`ml`],[`instant-yeast`,8,`g`],[`chicken-egg`,2,`pcs`],[`white-granulated-sugar`,85,`g`],[`unsalted-butter`,65,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`walnut`,400,`g`],[`honey`,150,`g`],[`whole-cow-milk`,90,`ml`],[`ground-cinnamon`,3,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:14,i:[]},{en:`Bake in a preheated 180°C oven for about 47 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 47 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:47,i:[]}];var d={slug:i,id:t,country:`SI`,region:a,servings:8,minutes:138,title:s,text:u,steps:g};export{o as country,d as default,t as id,r as minutes,a as region,l as servings,i as slug,g as steps,u as text,s as title};